qss:
QWidget { background: #160f22; color: #f4eaff; font-family: "Segoe UI", "Inter", sans-serif; font-size: 10pt; }
QMainWindow, QDialog { background: #160f22; }
QLabel { background: transparent; }
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface { background: #211630; border: 1px solid #5e4778; border-radius: 16px; }
QLabel#TitleLabel { font-size: 16pt; font-weight: 700; color: #f4eaff; }
QLabel#SubtleLabel { color: #bda7d6; }
QPushButton { background: #35234b; color: #f4eaff; border: 1px solid #5e4778; border-radius: 12px; padding: 8px 12px; }
QPushButton:hover { background: #432b5e; }
QPushButton#AccentButton { background: #8b5cf6; border: 1px solid #a78bfa; color: #ffffff; font-weight: 700; }
QPushButton#AccentButton:hover { background: #a78bfa; }
QPushButton#DangerButton { background: #552443; }
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser, QSpinBox { background: #100b18; color: #f4eaff; border: 1px solid #5e4778; border-radius: 12px; padding: 8px; }
QListWidget::item { border-radius: 10px; padding: 8px; margin: 2px; }
QListWidget::item:selected { background: #3a2854; border: 1px solid #8b5cf6; }
QScrollArea { border: none; background: transparent; }
QScrollBar:vertical { background: #211630; width: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:vertical { background: #5e4778; min-height: 32px; border-radius: 7px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QProgressBar { border: 1px solid #5e4778; border-radius: 10px; background: #100b18; text-align: center; min-height: 18px; }
QProgressBar::chunk { background: #8b5cf6; border-radius: 8px; }
QFrame#AssistantBubbleCard { background: #211630; border: 1px solid #5e4778; border-left: 4px solid #a78bfa; border-radius: 16px; }
QFrame#UserBubbleCard { background: #3a2854; border: 1px solid #5e4778; border-radius: 16px; }
